// Copies the Go Go HarmoniYo brand files the game uses from docs/design/brand/ (generated by
// tools/design/brand/build.py, registered as brand-identity and brand-yo-defaults) into
// public/brand/ (gitignored), so Vite ships them at fixed paths for the favicon, the web app
// manifest and the lobby/results/corner images. Never edit the copies; rebuild the sources.
//   node scripts/brand-assets.mjs
import { copyFileSync, mkdirSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, '..', '..', '..', 'docs', 'design', 'brand');
const out = join(here, '..', 'public', 'brand');

const BRAND_FILES = [
  'favicon.svg',
  'favicon.ico',
  'apple-touch-icon.png',
  'icon-192.png',
  'icon-512.png',
  'icon-maskable-192.png',
  'icon-maskable-512.png',
  'logo-stacked-dark.svg',
  'mark-dark.svg',
  'yo/yo-idle.svg',
  'yo/yo-ring.svg',
  'yo/yo-cheer.svg',
  'yo/yo-cheer-hands.svg',
];

mkdirSync(out, { recursive: true });
for (const f of BRAND_FILES) copyFileSync(join(src, f), join(out, basename(f)));
console.log(`brand: ${BRAND_FILES.length} files → ${out}`);
